		<div class="elementor-element elementor-element-84b5a8d e-flex e-con-boxed e-con e-child" data-id="84b5a8d" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
				<div class="elementor-element elementor-element-5f9d73f elementor-widget elementor-widget-text-editor" data-id="5f9d73f" data-element_type="widget" data-widget_type="text-editor.default">
