		<div class="elementor-element elementor-element-a47091d e-flex e-con-boxed e-con e-parent" data-id="a47091d" data-element_type="container" data-settings="{&quot;background_background&quot;:&quot;classic&quot;,&quot;jet_parallax_layout_list&quot;:[]}">
